write('/about/','Our philosophy','Meet RITUWILD: thoughtful digital resources for a clearer, calmer everyday.','''<section class="wrap page-intro"><div class="eyebrow">OUR PHILOSOPHY</div><h1>Beautiful is good.<br><em>Beautifully useful is better.</em></h1><p>RITUWILD began with a simple idea: the things that help us manage life should feel as considered as the life we want to build.</p></section><section class="wrap about-grid section"><div><h2>A practical kind<br>of <em>luxury.</em></h2><p>A clear page. A useful question. A plan that makes a busy day feel a little more manageable. We believe good design earns its place by helping you do something.</p><p>Our opening collection brings that idea to life direction, financial clarity, training habits and emotional reflection. Each resource has a specific purpose and room for your own approach.</p></div><div class="values"><article><span>01</span><h3>Clarity over clutter.</h3><p>Give each page a purpose. Make the next step easy to find.</p></article><article><span>02</span><h3>Care in the details.</h3><p>Readable layouts, thoughtful prompts and a coherent visual language.</p></article><article><span>03</span><h3>Room for real life.</h3><p>Useful tools that support your routines and leave space for individuality.</p></article></div></section><section class="wrap section philosophy"><div class="eyebrow">OUR WIDER WORLD</div><h2>Independent voices.<br><em>A shared sensibility.</em></h2><p>RITUWILD sits alongside HAYVN and WILDWIRE. Different experiences, connected by creativity and an interest in living with more intention.</p><a class="button" href="/shop/">Explore RITUWILD ↗</a></section>''','about')
faq=[('Are the paid products available yet?','The Inner Compass is complete and has a free eight-page preview. Paid checkout is being connected and tested, so paid orders are not accepted yet. Financial Clarity, The Next Chapter and Steady Strength now have complete files and partial previews; their checkouts are not enabled.'),('How can I get the free planner?','Download the two-page PDF from its product page. No account or email address is needed.'),('Are these physical products?','No. RITUWILD creates digital resources. The free planner is a PDF file that you can view or print. Each product page states the actual formats and current checkout status. No physical item is shipped.'),('Can I print the planner on A4?','Yes. Its pages are US Letter size; choose Fit to page in your print settings for A4. Preview the margins before printing.'),('Can I edit the PDFs?','The free Weekly Reset Planner is printable. The complete Inner Compass includes a writable PDF with 122 answer fields and a separate A4 print edition. Save a personal copy in a compatible PDF reader and test that an answer remains after reopening. The budgeting workbook is built as an editable XLSX, with application-compatibility limits explained on its product page.'),('Which currency are the prices in?','The displayed paid-product prices are planned launch prices in US dollars. Checkout pricing, taxes and any currency conversion will be confirmed before paid sales begin.'),('Can I share or resell a download?','The free planner is for personal use. Please share its product-page link rather than redistributing the file. Paid-product license options will be finalized before sales begin.'),('Can I use these with clients?','A professional-use license has not yet been offered. Do not redistribute files or include them in paid client packages without written permission.'),('Will there be French versions?','The current development version is in English. French-language requirements and product localization must be resolved before commercial launch from Quebec.')]
write('/faq/','Questions & answers','Formats, printing, availability and useful answers about RITUWILD digital products.','<section class="wrap page-intro"><div class="eyebrow">GOOD TO KNOW</div><h1>A little <em>clarity.</em></h1><p>Questions about the collection, the files and what comes next.</p></section><section class="wrap narrow section">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faq)+'</section>')
write('/contact/','Contact','Contact RITUWILD for product questions and download support.',f'''<section class="wrap page-intro"><div class="eyebrow">GET IN TOUCH</div><h1>A thoughtful conversation<br>starts with <em>hello.</em></h1><p>Questions about a journal, your files or finding the right tool? Get in touch.</p></section><section class="wrap narrow section"><h2>Customer support</h2><p>Email <a href="mailto:{SUPPORT}">{SUPPORT}</a> for product questions or help with your download.</p><a class="button" href="mailto:{SUPPORT}">Email RITUWILD ↗</a><h3>Help us find your order</h3><p>If you purchased through Payhip, include the product name and order reference from your receipt. Check your inbox and spam folder for the download email first. Never send passwords, payment-card details or sensitive journal entries.</p><p>For questions about formats, printing and PDF compatibility, visit our answers below.</p><a class="button" href="/faq/">Browse questions & answers ↗</a></section>''')
policies={
'privacy':('Privacy','This development storefront does not include analytics, advertising trackers, newsletter capture or a contact submission form. It does not intentionally collect personal information through those features. The free Your Next Step exercise processes your answers only in the current browser page. The tool does not submit your answers to RITUWILD or save them to browser storage.','Hosting providers may process connection information. Visiting HAYVN or WILDWIRE takes you to an independent website with its own practices. A complete privacy notice naming the seller, privacy contact, processors, retention periods, rights and any international transfers must be finalized before public launch.'),
'terms':('Terms of service','The storefront is in development. Paid products are not offered for sale and the displayed prices are proposed launch prices in USD. No paid orders can be placed here.','Commercial terms must identify the seller, contact details, applicable consumer rights, checkout terms, delivery and dispute processes before paid sales. This page is a development status notice, not final commercial terms.'),
'license':('Digital product license','The Weekly Reset Planner may be downloaded and printed repeatedly for your own personal use. You may not resell it, redistribute its file, remove its branding, or claim it as your own. Share the product-page link with others.','Professional-use permissions and paid-product licenses must be finalized before sales begin. Original RITUWILD layouts and text remain protected by applicable intellectual property law.'),
'refunds':('Refund policy','No paid orders are being accepted in this development version. The Weekly Reset Planner is free. There are currently no RITUWILD purchases to refund through this storefront.','A clear refund and cancellation policy, preserving mandatory consumer rights and describing how to report duplicate charges, faulty files or delivery issues, must be finalized with the checkout platform before paid sales begin.')}
for slug,(title,p1,p2) in policies.items():write('/'+slug+'/',title,title+' and development status for RITUWILD.','<section class="wrap page-intro"><div class="eyebrow">CUSTOMER INFORMATION</div><h1>'+title+'</h1><p>Development status · October 2026</p></section><section class="wrap narrow section"><p>'+p1+'</p><p>'+p2+'</p><div class="note">Commercial launch is pending. Final seller information and any required professional review remain outstanding.</div></section>')
write('/your-next-step/','Your next step','A free guided exercise to turn one life priority into a practical next action.','''<section class="wrap page-intro"><div class="eyebrow">A FREE RITUWILD PRACTICE</div><h1>One honest priority.<br><em>One useful next step.</em></h1><p>Choose one area of your life. Name a change that matters. Make the first action small enough to begin this week.</p></section><section class="wrap section step-tool"><form id="step-form" class="step-builder" autocomplete="off"><div><span class="eyebrow">01 / CHOOSE YOUR FOCUS</span><label for="step-focus">Where would you like more clarity?</label><select id="step-focus" required><option value="">Choose an area</option><option>Life direction</option><option>Financial clarity</option><option>Training & habits</option><option>Emotional clarity</option></select></div><div><span class="eyebrow">02 / NAME WHAT MATTERS</span><label for="step-goal">What would you like to change or understand?</label><textarea id="step-goal" maxlength="400" required placeholder="For example: I want to understand where my money goes."></textarea><small>Keep it specific. Your answer can be simple.</small></div><div><span class="eyebrow">03 / MAKE IT SMALL</span><label for="step-action">What is one action you can take?</label><textarea id="step-action" maxlength="300" required placeholder="For example: Review the last seven days of spending for 15 minutes."></textarea><label for="step-when">When will you make room for it?</label><input id="step-when" maxlength="120" required placeholder="For example: Sunday after breakfast"></div><div><span class="eyebrow">04 / PLAN TO RETURN</span><label for="step-review">When will you check in with yourself?</label><input id="step-review" maxlength="120" required placeholder="For example: Next Sunday evening"><button class="button" type="submit">Create my action card ↗</button></div><p class="small">This exercise stays in this page. RITUWILD does not receive or store your answers. Print the card if you want to keep it.</p></form><aside id="step-result" class="step-result" hidden tabindex="-1" aria-labelledby="step-result-title"><span class="eyebrow">RITUWILD / YOUR NEXT STEP</span><h2 id="step-result-title">A direction.<br>A beginning.</h2><dl><div><dt>My focus</dt><dd id="result-focus"></dd></div><div><dt>What matters to me</dt><dd id="result-goal"></dd></div><div><dt>My next small action</dt><dd id="result-action"></dd></div><div><dt>When I will begin</dt><dd id="result-when"></dd></div><div><dt>My next check-in</dt><dd id="result-review"></dd></div></dl><p>At your check-in, ask: What happened? What helped? What is one adjustment I can make?</p><button id="print-step" type="button" class="button">Print my action card ↓</button><span class="small">Beautiful Tools for Real Life.</span></aside></section>''','step')
